// SYNTHETIC parity test: website planner copy vs the golden fixture generated by the Engage backend planner.
import test from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { planGiftJob, type GiftRow } from "../lib/portal-v2/gift-identity-plan";
const FIXTURE = new URL("./fixtures/gift-identity-golden.json", import.meta.url);
const G = JSON.parse(readFileSync(FIXTURE, "utf8")) as { cases: { name: string; generated?: boolean; base?: Base; decided?: GiftRow[]; held?: number[]; total?: number; cols?: number; expect: { jobId: string; batchHashes: string[]; slices: number[][]; requestIds: string[] } }[]; refusals: { name: string; base: Base; decided: GiftRow[]; held: number[]; total: number; cols: number }[] };
type Base = Parameters<typeof planGiftJob>[0];
const base = (n: string): Base => ({ client: "fict", registrationId: "fict_gifts", registrationVersion: 3, registrationDigest: "d".repeat(64), actor: "Pat Example (as stated)", fileName: n, fileDigest: "f".repeat(64), fileDate: "2026-10-31" });
const nw = (o: number, v: Record<string, string>, p = 7001): GiftRow => ({ ordinal: o, action: "new", person: p, values: v, expected: null });
const big = "\u20ac".repeat(4000);
const GEN: Record<string, () => { base: Base; decided: GiftRow[]; held: number[]; total: number; cols: number }> = {
  "work-budget-606": () => ({ base: base("big.csv"), cols: 13, total: 606, held: [7, 108, 209, 310, 411, 512], decided: Array.from({ length: 606 }, (_, o) => o).filter((o) => o % 101 !== 7).map((o) => nw(o, { Gift_Amount: String(100 + o), Gift_Date: "2026-02-01T00:00:00" }, 7000 + (o % 9) + 1)) }),
  "byte-heavy": () => ({ base: base("wide.csv"), cols: 12, total: 40, held: [], decided: Array.from({ length: 40 }, (_, o) => ({ ordinal: o, action: "correct" as const, giftId: `${(o + 1).toString(16).padStart(8, "0")}-0000-4000-8000-00000000abcd`, person: 7001, values: Object.fromEntries(Array.from({ length: 12 }, (_, i) => [`Note${i}`, big.slice(1) + "y"])), expected: Object.fromEntries(Array.from({ length: 12 }, (_, i) => [`Note${i}`, big])) })) }),
};
test("[PARITY] planner output equals the shared golden fixture (mixed actions, unicode/decimal/date/null, key order, 606 work budget, byte-heavy slicing, refusals)", () => {
  assert.equal(G.cases.length, 4);
  for (const c of G.cases) {
    const inp = c.generated ? GEN[c.name]() : { base: c.base!, decided: c.decided!, held: c.held!, total: c.total!, cols: c.cols! };
    const p = planGiftJob(inp.base, inp.decided, inp.held, inp.total, inp.cols);
    assert.equal(p.jobId, c.expect.jobId, c.name);
    assert.deepEqual(p.manifest.batches.map((b) => b.hash), c.expect.batchHashes, c.name);
    assert.deepEqual(p.manifest.batches.map((b) => [b.first, b.last]), c.expect.slices, c.name);
    assert.deepEqual(p.requests.map((r) => r.requestId), c.expect.requestIds, c.name);
  }
  assert.equal(G.cases[0].expect.jobId, G.cases[1].expect.jobId, "key order does not change identity");
  for (const r of G.refusals) assert.throws(() => planGiftJob(r.base, r.decided, r.held, r.total, r.cols), r.name);
});
